Command `cat > /workspace/test_poc2.cpp << 'EOF'
#include <cstdint>
#include <cstring>
#include <json/json.h>
#include <memory>
#include <stdio.h>
#include <stdlib.h>
#include <string>

int main(int argc, char** argv) {
  if (argc < 2) {
    fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
    return 1;
  }

  FILE* f = fopen(argv[1], "rb");
  if (!f) {
    fprintf(stderr, "Cannot open %s\n", argv[1]);
    return 1;
  }
  fseek(f, 0, SEEK_END);
  long fsize = ftell(f);
  fseek(f, 0, SEEK_SET);

  uint8_t* buf = new uint8_t[fsize];
  fread(buf, 1, fsize, f);
  fclose(f);

  // Replicate the fuzz target logic EXACTLY
  Json::CharReaderBuilder builder;

  if (fsize < 4) {
    delete[] buf;
    return 0;
  }

  uint32_t hash_settings = *(const uint32_t*)buf;
  const uint8_t* data = buf + 4;

  builder.settings_["failIfExtra"] = hash_settings & (1 << 0);
  builder.settings_["allowComments_"] = hash_settings & (1 << 1);
  builder.settings_["strictRoot_"] = hash_settings & (1 << 2);
  builder.settings_["allowDroppedNullPlaceholders_"] = hash_settings & (1 << 3);
  builder.settings_["allowNumericKeys_"] = hash_settings & (1 << 4);
  builder.settings_["allowSingleQuotes_"] = hash_settings & (1 << 5);
  builder.settings_["failIfExtra_"] = hash_settings & (1 << 6);
  builder.settings_["rejectDupKeys_"] = hash_settings & (1 << 7);
  builder.settings_["allowSpecialFloats_"] = hash_settings & (1 << 8);

  std::unique_ptr<Json::CharReader> reader(builder.newCharReader());

  Json::Value root;
  const char* data_str = reinterpret_cast<const char*>(data);
  // BUG: size is not decremented, so end pointer is 4 bytes past actual data
  try {
    reader->parse(data_str, data_str + fsize, &root, nullptr);
  } catch (Json::Exception const&) {
  }

  delete[] buf;
  return 0;
}
